INSERT INTO catalog_contents VALUES(35,35,'review','{"intro":"\"Dasar K3\" adalah program di bidang dasar-dasar keselamatan dan kesehatan kerja (K3) untuk berbagai sektor. Peserta mempelajari cara mengenali bahaya kerja, menggunakan APD dengan benar, serta melaporkan temuan secara tertib. Sebagai program tingkat awal, pembahasan tidak menuntut pengalaman formal yang panjang. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Dasar K3\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk petugas K3, pengawas lapangan, dan personel yang baru ditugasi menangani keselamatan kerja","objectives":["Menautkan lingkup \"Dasar K3\" dengan tanggung jawab nyata peserta di tempat kerja","Menjelaskan peran dan tanggung jawab fungsi K3 pada unit kerja masing-masing","Mengidentifikasi bahaya harian dan menilai tingkat risikonya","Menerapkan penggunaan APD sesuai kondisi kerja","Mendokumentasikan dan melaporkan temuan K3 secara baku"],"curriculum":["Bahaya kerja umum dan penyakit akibat kerja","Gambaran singkat sistem manajemen keselamatan kerja","APD: pemilihan, penggunaan, dan pemeriksaan","Pengamatan kegiatan dan pelaporan di lapangan","Studi kasus penerapan di tempat kerja"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Dasar K3\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar