INSERT INTO catalog_contents VALUES(96,96,'review','{"intro":"\"Pipe Fitter\" adalah program di bidang pekerjaan las, persiapan permukaan (coating\/painting\/blasting), dan proteksi material. Peserta mempelajari bahaya proses las listrik, permukaan, serta pemeriksaan visual hasil kerja. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Pipe Fitter\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk welder, helper, inspektur las, operator coating\/blasting, dan QC area fabrikasi","objectives":["Menautkan lingkup \"Pipe Fitter\" dengan tanggung jawab nyata peserta di tempat kerja","Menyiapkan area kerja las dengan pembatas aman","Menggunakan PPE sesuai proses kerja (las, blasting, coating)","Mengenali cacat umum hasil las\/permukaan secara visual","Melaporkan kondisi tidak aman (percikan api, sisa material) secara cepat"],"curriculum":["Bahaya proses las: percikan, radiasi, gas hasil pembakaran","Ventilasi dan kontrol api pada area terbatas","Persiapan permukaan: blasting, primer, cat lapis","Korosi\/perkaratan: penyebab dan tindakan proteksi dasar","Ringkasan inspeksi visual tingkat awal"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Pipe Fitter\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"Pipe Fitter\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halaman ini dan sebutkan nama program tersebut. Tim kami memandu langkah pendaftaran yang berlaku saat ini."},{"question":"Jumlah peserta minimum berapa untuk bisa jalan?","answer":"Batas jumlah peserta tidak tercantum di katalog sumber; mohon konfirmasi langsung kepada tim kami lewat WhatsApp."},{"question":"Apakah tersedia pelaksanaan di lokasi kami?","answer":"Penempatan pelaksanaan disepakati saat konsultasi. Semua pertanyaan jadwal dan lokasi bisa langsung diajukan lewat kanal WhatsApp di halaman ini."}]}','2026-10-23 18:47:51',NULL,'2026-10-23 18:47:51','2026-10-23 18:47:51');
