INSERT INTO catalog_contents VALUES(102,102,'review','{"intro":"\"JSA (Job Safety Analysis)\" adalah program di bidang peningkatan kapasitas manajemen, kepemimpinan, dan pengelolaan kegiatan organisasi. Peserta mempelajari kerangka kerja praktis: perumusan tujuan, pembagian tugas, umpan balik kinerja, dan pemantauan hasil. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan kerangka kerja praktis agar pekerjaan tim berjalan lebih tertib, terarah, dan terukur setelah program selesai.","audience":"Program paling relevan untuk manajer, supervisor, staf HRD, pelaku usaha, dan personel yang mengelola program\/kegiatan tim","objectives":["Menautkan lingkup \"JSA (Job Safety Analysis)\" dengan tanggung jawab nyata peserta di tempat kerja","Menyusun rencana kegiatan dengan indikator yang jelas","Menerapkan delegasi pelaksanaan sesuai kemampuan anggota tim","Memberikan umpan balik kinerja secara konstruktif","Mengelola data sederhana untuk pengambilan keputusan"],"curriculum":["Dasar manajemen berbasis proses","Perumusan tujuan kerja dan indikatornya","Komunikasi efektif dan umpan balik","Pengelolaan rapat\/dokumen yang efektif","Studi kasus penerapan di organisasi"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"JSA (Job Safety Analysis)\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"JSA (Job Safety Analysis)\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halaman ini dan sebutkan nama program tersebut. Tim kami memandu langkah pendaftaran yang berlaku saat ini."},{"question":"Jumlah peserta minimum berapa untuk bisa jalan?","answer":"Batas jumlah peserta tidak tercantum di katalog sumber; mohon konfirmasi langsung kepada tim kami lewat WhatsApp."},{"question":"Apakah tersedia pelaksanaan di lokasi kami?","answer":"Penempatan pelaksanaan disepakati saat konsultasi. Semua pertanyaan jadwal dan lokasi bisa langsung diajukan lewat kanal WhatsApp di halaman ini."}]}','2026-10-23 18:47:51',NULL,'2026-10-23 18:47:51','2026-10-23 18:47:51');
