INSERT INTO catalog_contents VALUES(141,141,'review','{"intro":"\"NDT (Non Destructive Test)\" adalah program di bidang pekerjaan las, persiapan permukaan (coating\/painting\/blasting), dan proteksi material. Peserta mempelajari bahaya proses las listrik, permukaan, serta pemeriksaan visual hasil kerja. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"NDT (Non Destructive Test)\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk welder, helper, inspektur las, operator coating\/blasting, dan QC area fabrikasi","objectives":["Menautkan lingkup \"NDT (Non Destructive Test)\" dengan tanggung jawab nyata peserta di tempat kerja","Menyiapkan area kerja las dengan pembatas aman","Menggunakan PPE sesuai proses kerja (las, blasting, coating)","Mengenali cacat umum hasil las\/permukaan secara visual","Melaporkan kondisi tidak aman (percikan api, sisa material) secara cepat"],"curriculum":["Bahaya proses las: percikan, radiasi, gas hasil pembakaran","Ventilasi dan kontrol api pada area terbatas","Persiapan permukaan: blasting, primer, cat lapis","Korosi\/perkaratan: penyebab dan tindakan proteksi dasar","Ringkasan inspeksi visual tingkat awal"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"NDT (Non Destructive Test)\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"NDT (Non Destructive Test)\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halaman ini dan sebutkan nama program tersebut. Tim kami memandu langkah pendaftaran yang berlaku saat ini."},{"question":"Jumlah peserta minimum berapa untuk bisa jalan?","answer":"Batas jumlah peserta tidak tercantum di katalog sumber; mohon konfirmasi langsung kepada tim kami lewat WhatsApp."},{"question":"Apakah tersedia pelaksanaan di lokasi kami?","answer":"Penempatan pelaksanaan disepakati saat konsultasi. Semua pertanyaan jadwal dan lokasi bisa langsung diajukan lewat kanal WhatsApp di halaman ini."}]}','2026-10-23 18:47:53',NULL,'2026-10-23 18:47:53','2026-10-23 18:47:53');
INSERT INTO catalog_contents VALUES(142,142,'review','{"intro":"\"K3 Pertambangan\" adalah program di bidang keselamatan pekerjaan sektor pertambangan, perkebunan, dan sumber daya alam. Peserta mempelajari bahaya lingkungan lapangan, komunikasi unit bergerak, dan tata pelaporan di site. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"K3 Pertambangan\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk personel site tambang\/kebun, surveyor, pengawas lapangan, dan personel reklamasi","objectives":["Menautkan lingkup \"K3 Pertambangan\" dengan tanggung jawab nyata peserta di tempat kerja","Mengidentifikasi bahaya khas site tambang\/kebun beserta pengendalinya","Menerapkan komunikasi radio dan pelaporan kondisi site","Menata zona aman di sekitar alat berat tambang","Mengenali tindakan dasar reklamasi dan perlindungan lingkungan site"],"curriculum":["Sistem pengawasan bahaya di area tambang","Kerja di medan berat: lereng, lubang, lorong","Reklamasi dan pengelolaan lingkungan pasca-aktivitas","Bahaya khas kebun\/kehutanan: pestisida, panas, fauna","Ringkasan kasus kecelakaan sektor tambang"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"K3 Pertambangan\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"K3 Pertambangan\"?","answer":"Kirim pesan melalui salah