INSERT INTO catalog_contents VALUES(180,180,'review','{"intro":"\"OPERATOR JIB CRANE\" adalah program di bidang kegiatan pembebanan (lifting) dan pengoperasian pesawat angkat. Peserta mempelajari pembacaan rencana lifting, pemeriksaan alat ikat, dan komunikasi sinyal operator-rigger. Karena menyasar pelaksana\/praktisi, pembahasan menekankan langkah kerja langsung, pemeriksaan pra-operasi, dan penggunaan APD. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"OPERATOR JIB CRANE\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk rigger, operator crane, lifting supervisor, dan personel logistik yang terlibat aktivitas lifting","objectives":["Menautkan lingkup \"OPERATOR JIB CRANE\" dengan tanggung jawab nyata peserta di tempat kerja","Menyusun rencana lifting sederhana sesuai kondisi lapangan","Memeriksa kelayakan sling dan aksesori ikat sebelum digunakan","Menggunakan sinyal komunikasi operator-rigger secara konsisten","Menetapkan zona sinyal aman di bawah alat angkat"],"curriculum":["Jenis pesawat angkat dan batas penggunaannya","Rencana lifting dan identifikasi zona berbahaya","Rigging: jenis sling, sudut ikat, beban aman","Sinyal komunikasi antar operator dan rigger di lapangan","Kasus kegagalan lifting dan pencegahannya"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"OPERATOR JIB CRANE\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu prog