INSERT INTO catalog_contents VALUES(191,191,'review','{"intro":"\"Kendaraan Laut Darat dan Udara\" adalah program di bidang defensive driving dan keselamatan pengemudian kendaraan operasional. Peserta mempelajari antisipasi risiko berkendara, manajemen kelelahan, dan pemeriksaan harian kendaraan. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Kendaraan Laut Darat dan Udara\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk pengemudi operasional, driver armada truk, dan pengawas fleet perusahaan","objectives":["Menautkan lingkup \"Kendaraan Laut Darat dan Udara\" dengan tanggung jawab nyata peserta di tempat kerja","Menerapkan prinsip defensif dalam berkendara di jalan operasional","Menata jarak aman dan kecepatan sesuai kondisi jalan","Mengenali tanda kelelahan dan memutuskan berhenti dengan benar","Menjalankan pemeriksaan pra-rute kendaraan"],"curriculum":["Faktor kecelakaan: manusia, mesin, lingkungan","Jarak aman dan teknik rem dan antisipasi kecepatan","Berkendara malam, hujan, dan medan terbatas","Checklist kendaraan harian: ban, rem, lampu","Ringkasan insiden jalan raya khas operasional"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Kendaraan Laut Darat dan Udara\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"Kendaraan Laut Darat dan Udar