INSERT INTO catalog_contents VALUES(207,207,'review','{"intro":"\"Korosi Perkaratan Alat\" adalah program di bidang pekerjaan las, persiapan permukaan (coating\/painting\/blasting), dan proteksi material. Peserta mempelajari bahaya proses las listrik, permukaan, serta pemeriksaan visual hasil kerja. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Korosi Perkaratan Alat\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk welder, helper, inspektur las, operator coating\/blasting, dan QC area fabrikasi","objectives":["Menautkan lingkup \"Korosi Perkaratan Alat\" dengan tanggung jawab nyata peserta di tempat kerja","Menyiapkan area kerja las dengan pembatas aman","Menggunakan PPE sesuai proses kerja (las, blasting, coating)","Mengenali cacat umum hasil las\/permukaan secara visual","Melaporkan kondisi tidak aman (percikan api, sisa material) secara cepat"],"curriculum":["Bahaya proses las: percikan, radiasi, gas hasil pembakaran","Ventilasi dan kontrol api pada area terbatas","Persiapan permukaan: blasting, primer, cat lapis","Korosi\/perkaratan: penyebab dan tindakan proteksi dasar","Ringkasan inspeksi visual tingkat awal"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Korosi Perkaratan Alat\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"Korosi Perkaratan Alat\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halaman ini dan sebutkan nama program tersebut. Tim kami memandu langkah pendaftaran yang berlaku saat ini."},{"question":"Jumlah peserta minimum berapa untuk bisa jalan?","answer":"Batas jumlah peserta tidak tercantum di katalog sumber; mohon konfirmasi langsung kepada tim kami lewat WhatsApp."},{"question":"Apakah tersedia pelaksanaan di lokasi kami?","answer":"Penempatan pelaksanaan disepakati saat konsultasi. Semua pertanyaan jadwal dan lokasi bisa langsung diajukan lewat kanal WhatsApp di halaman ini."}]}','2026-10-23 18:47:54',NULL,'2026-10-23 18:47:54','2026-10-23 18:47:54');
INSERT INTO catalog_contents VALUES(208,208,'review','{"intro":"\"Food Handler\" adalah program di bidang bahaya bahan kimia, keselamatan laboratorium, dan higiene industri. Peserta mempelajari label GHS\/SDS, pengelompokan bahan, ventilasi, dan langkah pertolongan dasar saat kontak bahan. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Food Handler\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk petugas kimia, pekerja laboratorium, operator penanganan bahan, dan staf lingkungan kerja","objectives":["Menautkan lingkup \"Food Handler\" dengan tanggung jawab nyata peserta di tempat kerja","Membaca label GHS dan lembar data keselamatan (SDS) dengan benar","Menata penyimpanan bahan kimia sesuai kelompok bahayanya","Menyiapkan tanggul tumpahan kecil (spill kit)","Menggunakan APD kimia sesuai sifat bahan"],"curriculum":["Klasifikasi bahaya kimia dan label GHS","SDS: bagian penting dan kapan membacanya","APD kimia: pemilihan dan batas pakai","Higiene industri dasar: jalur masuk bahaya ke tubuh","Bahan khusus (asbes, metal berat, fumigasi) bila program menekankan"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Food Handler\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"Food Handler\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halama