INSERT INTO catalog_contents VALUES(209,209,'review','{"intro":"\"Operator K3 Mesin\" adalah program di bidang dasar-dasar keselamatan dan kesehatan kerja (K3) untuk berbagai sektor. Peserta mempelajari cara mengenali bahaya kerja, menggunakan APD dengan benar, serta melaporkan temuan secara tertib. Karena menyasar pelaksana\/praktisi, pembahasan menekankan langkah kerja langsung, pemeriksaan pra-operasi, dan penggunaan APD. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Operator K3 Mesin\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk petugas K3, pengawas lapangan, dan personel yang baru ditugasi menangani keselamatan kerja","objectives":["Menautkan lingkup \"Operator K3 Mesin\" dengan tanggung jawab nyata peserta di tempat kerja","Menjelaskan peran dan tanggung jawab fungsi K3 pada unit kerja masing-masing","Mengidentifikasi bahaya harian dan menilai tingkat risikonya","Menerapkan penggunaan APD sesuai kondisi kerja","Mendokumentasikan dan melaporkan temuan K3 secara baku"],"curriculum":["Bahaya kerja umum dan penyakit akibat kerja","Gambaran singkat sistem manajemen keselamatan kerja","APD: pemilihan, penggunaan, dan pemeriksaan","Pengamatan kegiatan dan pelaporan di lapangan","Studi kasus penerapan di tempat kerja"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Operator K3 Mesin\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"Operator K3 Mesin\"?","answer":"Kirim pesan melalui salah satu tombol WhatsApp di halaman ini dan sebutkan nama program tersebut. Tim kami memandu langkah pendaftaran yang berlaku saat ini."},{"question":"Jumlah peserta minimum berapa untuk bisa jalan?","answer":"Batas jumlah peserta tidak tercantum di katalog sumber; mohon konfirmasi langsung kepada tim kami lewat WhatsApp."},{"question":"Apakah tersedia pelaksanaan di lokasi kami?","answer":"Penempatan pelaksanaan disepakati saat konsultasi. Semua pertanyaan jadwal dan lokasi bisa langsung diajukan lewat kanal WhatsApp di halaman ini."}]}','2026-10-23 18:47:54',NULL,'2026-10-23 18:47:54','2026-10-23 18:47:54');
INSERT INTO catalog_contents VALUES(210,210,'review','{"intro":"\"DDC (Defensive Driving Course)\" adalah program di bidang defensive driving dan keselamatan pengemudian kendaraan operasional. Peserta mempelajari antisipasi risiko berkendara, manajemen kelelahan, dan pemeriksaan harian kendaraan. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"DDC (Defensive Driving Course)\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk pengemudi operasional, driver armada truk, dan pengawas fleet perusahaan","objectives":["Menautkan lingkup \"DDC (Defensive Driving Course)\" dengan tanggung jawab nyata peserta di tempat kerja","Menerapkan prinsip defensif dalam berkendara di jalan operasional","Menata jarak aman dan kecepatan sesuai kondisi jalan","Mengenali tanda kelelahan dan memutuskan berhenti dengan benar","Menjalankan pemeriksaan pra-rute kendaraan"],"curriculum":["Faktor kecelakaan: manusia, mesin, lingkungan","Jarak aman dan teknik rem dan antisipasi kecepatan","Berkendara malam, hujan, dan medan terbatas","Checklist kendaraan harian: ban, rem, lampu","Ringkasan insiden jalan raya khas operasional"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"DDC (Defensive Driving Course)\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar program \"DDC (Defensive Driving Course