INSERT INTO catalog_contents VALUES(225,225,'review','{"intro":"\"Jasa Lingkungan Karbon\" adalah program di bidang pengelolaan limbah, pengendalian pencemaran, dan pengambilan sampel lingkungan. Peserta mempelajari alur penanganan limbah, catatan perpindahan, dan pengambilan contoh untuk pemeriksaan. Nama program dikutip persis dari katalog sumber, sedangkan lingkup akhir pelaksanaan disepakati bersama saat konsultasi.","purpose":"Tujuan program: membekali peserta dengan pemahaman dan kebiasaan kerja aman pada bidang \"Jasa Lingkungan Karbon\" agar tugas di lapangan dapat dijalankan lewat prosedur yang jelas.","audience":"Program paling relevan untuk petugas pengelola limbah, pengendali pencemaran udara\/air, operator lingkungan industri, dan staf lingkungan pabrik","objectives":["Menautkan lingkup \"Jasa Lingkungan Karbon\" dengan tanggung jawab nyata peserta di tempat kerja","Menjelaskan alur umum penyimpanan sementara dan penyerahan limbah","Melabeli dan mencatat perpindahan limbah secara tertib","Mengambil contoh sampel uji sesuai prosedur dasar","Membaca dan meneruskan data hasil pemantauan lingkungan"],"curriculum":["Sifat umum limbah dan sumber pencemarannya","Penyimpanan sementara, pelabelan, dan dokumen perpindahan","Teknik pengambilan contoh air\/tanah\/udara dasar","Catatan lingkungan: logbook dan pelaporan","Studi kasus penanganan tumpahan limbah kecil"],"documents":["Identitas peserta: nama lengkap, jabatan, instansi\/perusahaan","Kebutuhan jumlah peserta dan perkiraan waktu pelaksanaan","Gambaran kondisi alat\/area kerja bila program bersifat operasional"],"process":["Hubungi salah satu kanal WhatsApp resmi di halaman ini dan sebutkan program \"Jasa Lingkungan Karbon\"","Kirim kebutuhan Anda: jumlah peserta, perkiraan jadwal, dan catatan khusus","Tim kami membalas dengan pertanyaan penjajakan dan gambaran pelaksanaan","Kesepakatan lingkup dan jadwal disepakati lalu program terlaksana sesuai rencana"],"faqs":[{"question":"Bagaimana cara mendaftar progr